import type { CSSProperties } from 'react';

// Размер в rem, чтобы иконки масштабировались с интерфейсом
const toRem = (size: number | string): string =>
  typeof size === 'number' ? `${size / 16}rem` : size;

interface SFIconProps {
  size?: number | string;
  color?: string;
  className?: string;
  style?: CSSProperties;
  // Поворот внутри SVG (html2canvas плохо работает с CSS transform)
  rotate?: number;
}

